// --- Storybook mock server ---

/** A request as seen by the mock server: the URL path already has any
 * proxy prefix stripped, `pathParams` holds decoded `@httpLabel`
 * values, `query` the parsed query string, `body` the parsed JSON body. */
export interface MockRequest {
  method: string
  path: string
  pathParams: Record<string, string>
  query: Record<string, string | undefined>
  body: unknown
}

export interface MockResponse {
  status: number
  body: unknown
  headers: Record<string, string>
}

/** One URI path segment of an operation's route: a literal or a
 * `@httpLabel` capture. */
export type MockUriSegment = { readonly literal: string } | { readonly label: string }

/** A single operation's route + codecs. `decodeInput` turns a matched
 * request into the operation's typed input; `encodeBody` extracts the
 * HTTP response body from the typed output. */
export interface MockOperation<Handlers> {
  readonly key: keyof Handlers & string
  readonly method: string
  readonly segments: readonly MockUriSegment[]
  readonly decodeInput: (req: MockRequest) => unknown
  readonly encodeBody: (output: unknown) => unknown
}

export interface MockServiceDescriptor<Handlers> {
  readonly serviceName: string
  readonly operations: readonly MockOperation<Handlers>[]
}

/** Thrown from a handler to return an arbitrary HTTP status/body that
 * isn't one of the operation's declared, typed errors (e.g. a 503 to
 * exercise a generic failure path). */
export class MockHttpError extends Error {
  readonly status: number
  readonly body: unknown
  constructor(status: number, body: unknown = { message: 'Error' }) {
    super('MockHttpError ' + status)
    this.name = 'MockHttpError'
    this.status = status
    this.body = body
  }
}

/** A matched, ready-to-run mock operation: everything the shared adapter
 * needs to invoke one handler and encode its result. */
export interface MockMatch {
  run: (req: MockRequest) => Promise<MockResponse>
}

/** A bound service mock: a matcher from HTTP method + path to a runnable
 * operation, or `null` when this service handles no such route. */
export interface BoundMockService {
  serviceName: string
  match: (method: string, path: string) => MockMatch | null
}

const matchSegments = (
  segments: readonly MockUriSegment[],
  path: string,
): Record<string, string> | null => {
  const parts = path.split('/').filter((p) => p.length > 0)
  if (parts.length !== segments.length) return null
  const pathParams: Record<string, string> = {}
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    if ('literal' in seg) {
      if (seg.literal !== parts[i]) return null
    }
    else {
      pathParams[seg.label] = decodeURIComponent(parts[i])
    }
  }
  return pathParams
}

/** Binds a service descriptor to a partial set of handlers, producing a
 * matcher. An unimplemented operation that gets called throws, so stories
 * only implement the operations they exercise. A thrown generated error
 * (`XxxError`) is encoded to its declared status + `x-error-type`; a
 * `MockHttpError` to its status/body; anything else re-throws. */
export const mockService = <Handlers>(
  descriptor: MockServiceDescriptor<Handlers>,
  handlers: Partial<Handlers>,
): BoundMockService => ({
  serviceName: descriptor.serviceName,
  match: (method, path) => {
    for (const op of descriptor.operations) {
      if (op.method !== method) continue
      const pathParams = matchSegments(op.segments, path)
      if (pathParams === null) continue
      const handler = handlers[op.key] as
        | ((input: unknown) => unknown | Promise<unknown>)
        | undefined
      return {
        run: async (req): Promise<MockResponse> => {
          if (handler === undefined) {
            throw new Error(descriptor.serviceName + '.' + op.key + ' called but no mock handler was provided')
          }
          const input = op.decodeInput({ ...req, pathParams })
          try {
            const output = await handler(input)
            return { status: 200, body: op.encodeBody(output), headers: {} }
          } catch (err) {
            if (err instanceof MockHttpError) {
              return { status: err.status, body: err.body, headers: {} }
            }
            if (isTypedMockError(err)) {
              return { status: err.status, body: err.payload, headers: { 'x-error-type': err.errorType } }
            }
            throw err
          }
        },
      }
    }
    return null
  },
})

interface TypedMockError {
  status: number
  errorType: string
  payload: unknown
}

const isTypedMockError = (err: unknown): err is TypedMockError =>
  err instanceof Error &&
  typeof (err as { status?: unknown }).status === 'number' &&
  typeof (err as { errorType?: unknown }).errorType === 'string' &&
  'payload' in err

/** Routes a request across several bound services, returning the first
 * match. Stories pass the mocks for whichever services a screen touches. */
export const mockServices = (
  ...services: readonly BoundMockService[]
): ((method: string, path: string) => MockMatch | null) =>
  (method, path) => {
    for (const svc of services) {
      const m = svc.match(method, path)
      if (m !== null) return m
    }
    return null
  }

